// Package go_renderer renders the contract as Go source: the enums, the event types, the error codes and the envelope
// structs, in the package value_objects of the domain layer.
package go_renderer

import (
	"fmt"
	"go/format"
	"strconv"
	"strings"

	"github.com/DanielCalvo-Calvicia/telemetry/tools/contract_generator/internal/application"
	"github.com/DanielCalvo-Calvicia/telemetry/tools/contract_generator/internal/domain"
)

// package_name is the Go package of the generated files.
const package_name = "value_objects"

// generated_marker is the line that tells the Go tools, and every reader, that the file is generated.
const generated_marker = "// Code generated by contract_generator; DO NOT EDIT."

// Renderer renders the Go files.
type Renderer struct{}

// NewRenderer returns the Go renderer.
func NewRenderer() Renderer {
	return Renderer{}
}

// Render returns the four generated files, formatted with gofmt. The contract must be sorted.
func (Renderer) Render(contract domain.Contract) ([]domain.GeneratedFile, error) {
	rendered := []domain.GeneratedFile{
		{Name: "enums_generated.go", Content: []byte(render_enums(contract))},
		{Name: "event_types_generated.go", Content: []byte(render_event_types(contract))},
		{Name: "error_codes_generated.go", Content: []byte(render_error_codes(contract))},
		{Name: "envelope_generated.go", Content: []byte(render_structs(contract))},
	}
	for position, generated := range rendered {
		formatted, format_error := format.Source(generated.Content)
		if format_error != nil {
			return nil, fmt.Errorf("%w: %s: %w", application.ErrRenderCode, generated.Name, format_error)
		}
		rendered[position].Content = formatted
	}
	return rendered, nil
}

// header is the start of every file: the generated marker, the sources and the package clause.
func header(sources []string) string {
	var text strings.Builder
	text.WriteString(generated_marker + "\n")
	for _, source := range sources {
		text.WriteString("// Source: " + source + "\n")
	}
	text.WriteString("\npackage " + package_name + "\n")
	return text.String()
}

func render_enums(contract domain.Contract) string {
	var sources []string
	var body strings.Builder
	for _, enum := range contract.Enums {
		sources = append(sources, enum.Source)
		type_name := domain.PascalCase(enum.Name)
		fmt.Fprintf(&body, "\n// %s is the enum of %s.\ntype %s string\n", type_name, enum.Source, type_name)
		fmt.Fprintf(&body, "\n// The values of %s.\nconst (\n", type_name)
		var members []string
		for _, value := range enum.Values {
			member := type_name + domain.PascalCase(value)
			members = append(members, member)
			fmt.Fprintf(&body, "\t%s %s = %s\n", member, type_name, strconv.Quote(value))
		}
		fmt.Fprintf(&body, ")\n")
		fmt.Fprintf(&body, "\n// %sValues returns every value of %s, in the order of the contract.\n", type_name, type_name)
		fmt.Fprintf(&body, "func %sValues() []%s {\n\treturn []%s{%s}\n}\n", type_name, type_name, type_name, strings.Join(members, ", "))
	}
	return header(sources) + body.String()
}

func render_event_types(contract domain.Contract) string {
	var body strings.Builder
	var members []string
	if len(contract.EventTypes) > 0 {
		body.WriteString("\n// The event types of the registry.\nconst (\n")
		for _, event_type := range contract.EventTypes {
			member := "EventType" + domain.PascalCase(event_type.Name)
			members = append(members, member)
			fmt.Fprintf(&body, "\t%s = %s\n", member, strconv.Quote(event_type.Name))
		}
		body.WriteString(")\n")
	}
	body.WriteString("\n// EventTypes returns every registered event type, in alphabetical order.\n")
	fmt.Fprintf(&body, "func EventTypes() []string {\n\treturn []string{%s}\n}\n", strings.Join(members, ", "))
	return header([]string{domain.SourcePrefix + domain.RegistryPath}) + body.String()
}

func render_error_codes(contract domain.Contract) string {
	var body strings.Builder
	var members []string
	if len(contract.ErrorCodes) > 0 {
		body.WriteString("\n// The error codes of the catalog.\nconst (\n")
		for _, error_code := range contract.ErrorCodes {
			member := "ErrorCode" + domain.PascalCase(error_code.Code)
			members = append(members, member)
			fmt.Fprintf(&body, "\t%s = %s\n", member, strconv.Quote(error_code.Code))
		}
		body.WriteString(")\n")
	}
	body.WriteString("\n// ErrorCodeInfo describes an error code of the catalog.\ntype ErrorCodeInfo struct {\n")
	body.WriteString("\tCode string\n\tCategory FailureCategory\n\tDefaultMessage string\n}\n")
	body.WriteString("\n// ErrorCodes returns the catalog of error codes, in alphabetical order of the code.\n")
	body.WriteString("func ErrorCodes() []ErrorCodeInfo {\n\treturn []ErrorCodeInfo{\n")
	for position, error_code := range contract.ErrorCodes {
		fmt.Fprintf(&body, "\t\t{Code: %s, Category: %s, DefaultMessage: %s},\n",
			members[position], "FailureCategory"+domain.PascalCase(error_code.Category), strconv.Quote(error_code.DefaultMessage))
	}
	body.WriteString("\t}\n}\n")
	return header([]string{domain.SourcePrefix + domain.CatalogPath}) + body.String()
}

func render_structs(contract domain.Contract) string {
	var sources []string
	var body strings.Builder
	uses_attributes := false
	for _, declared := range contract.Structs {
		sources = append(sources, declared.Source)
		type_name := domain.PascalCase(declared.Name)
		fmt.Fprintf(&body, "\n// %s mirrors %s.\ntype %s struct {\n", type_name, declared.Source, type_name)
		for _, field := range declared.OrderedFields() {
			uses_attributes = uses_attributes || field.Kind == domain.KindAttributes
			tag := field.JSONName
			if !field.Required {
				tag += ",omitempty"
			}
			fmt.Fprintf(&body, "\t%s %s `json:%s`\n", domain.PascalCase(field.JSONName), go_type(field), strconv.Quote(tag))
		}
		body.WriteString("}\n")
	}
	if uses_attributes {
		body.WriteString("\n// Attributes are the key-value extensions of the consumer: scalars and lists of scalars.\n")
		body.WriteString("type Attributes map[string]any\n")
	}
	return header(sources) + body.String()
}

// go_type returns the Go type of a field. An optional struct, number, integer or boolean is a pointer, so omitempty
// drops only a value that was not given and never a zero one.
func go_type(field domain.Field) string {
	var name string
	pointer := false
	switch field.Kind {
	case domain.KindString:
		name = "string"
	case domain.KindNumber:
		name, pointer = "float64", true
	case domain.KindInteger:
		name, pointer = "int64", true
	case domain.KindBoolean:
		name, pointer = "bool", true
	case domain.KindEnum:
		name = domain.PascalCase(field.Ref)
	case domain.KindStruct:
		name, pointer = domain.PascalCase(field.Ref), true
	case domain.KindAttributes:
		name = "Attributes"
	default:
		name = "map[string]any"
	}
	if pointer && !field.Required {
		return "*" + name
	}
	return name
}
